import java.io.*;import java.net.*;import java.net.http.*;import java.nio.file.*;import java.util.*;
public final class Arsenal717ServerCheck {
 static void ok(boolean b,String m){if(!b)throw new AssertionError(m);System.out.println("PASS: "+m);}
 static DataInputStream call(String token,String op,ServerCheck.Writer writer,boolean modern)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);out.writeInt(GunnyServer.MAGIC);out.writeUTF(op);if(writer!=null)writer.write(out);HttpRequest.Builder req=HttpRequest.newBuilder(URI.create(ServerCheck.base+"/api")).header("Content-Type","application/octet-stream");if(modern)req.header("X-Gunny-Arsenal","2");if(token!=null)req.header("Authorization","Bearer "+token);DataInputStream in=new DataInputStream(new ByteArrayInputStream(ServerCheck.HTTP.send(req.POST(HttpRequest.BodyPublishers.ofByteArray(bytes.toByteArray())).build(),HttpResponse.BodyHandlers.ofByteArray()).body()));int status=in.readUnsignedByte();if(status!=0)throw new IOException(in.readUTF());return in;}
 static String login(String email,boolean modern)throws Exception{return call(null,"login",o->{o.writeUTF(email);o.writeUTF("test-password-123");},modern).readUTF();}
 static void reject(String token,String op,ServerCheck.Writer writer,boolean modern,String message)throws Exception{boolean blocked=false;try{call(token,op,writer,modern);}catch(IOException e){blocked=true;}ok(blocked,message);}
 static class Ground implements Battle.Ground{int radius;public boolean solid(int x,int y){return y>=170;}public int surface(int x,int y){return 170;}public void crater(int x,int y,int r){radius=r;}}
 static void rules(){
  for(int id:new int[]{0,3,5,9}){Battle.Ball ball=new Battle.Ball();ball.weapon=id;ok(Battle.gravity(ball)==11&&Battle.windStep(28,ball)==4,"Original weapon "+id+" retains gravity and wind");ok(Battle.baseDamage(id)==(id==0?290:330)&&Battle.baseRadius(id)==(id==0?15:12),"Original weapon "+id+" retains damage and crater radius");}
  for(int id:new int[]{2,4,7,1}){Ground ground=new Ground();Battle b=new Battle(ground);b.start(false);b.hotseat=true;b.units[0].weapon=id;b.units[0].angle=45;b.units[0].power=50;b.units[1].x=350;b.units[1].y=170;Battle.Ball ball=b.make(45,50);ball.x=350*256;ball.y=158*256;b.impact(ball);ok(b.units[1].hp==Battle.MAXHP-Battle.baseDamage(id)&&ground.radius==Battle.baseRadius(id),"Weapon "+id+" applies damage and terrain radius together");b.units[0].rage=100;b.pow=true;b.fire();ok(b.units[0].rage==0,"Weapon "+id+" consumes POW at shot release");for(int t=0;t<8&&b.ballCount==0;t++)b.tick();ok(b.ballCount>0&&b.balls[0].powered&&b.balls[0].damage==Battle.baseDamage(id)*170/100,"Weapon "+id+" emits a powered native projectile");ball.fly=true;ok(Battle.gravity(ball)==11&&Battle.windStep(28,ball)==4,"Plane flight keeps original physics with weapon "+id);}
  Battle.Ball pill=new Battle.Ball(),fridge=new Battle.Ball();pill.weapon=2;fridge.weapon=4;ok(Battle.gravity(fridge)>Battle.gravity(pill)&&Battle.windStep(28,fridge)<Battle.windStep(28,pill),"Fridge is heavier and less wind-sensitive than medicine");ok(Battle.weaponMaxAngle(1)<Battle.weaponMaxAngle(7),"Firecrackers and fruit have distinct angle ranges");
 }
 public static void main(String[] args)throws Exception{rules();CloudStore.Memory store=new CloudStore.Memory();store.register("new@717.test","test-password-123","New");store.register("old@717.test","test-password-123","Old");try(GunnyServer server=new GunnyServer(new InetSocketAddress("127.0.0.1",0),Path.of("backend/assets"),store)){ServerCheck.base="http://127.0.0.1:"+server.port();String a=login("new@717.test",true),b=login("old@717.test",false);GunnyServer.Session sa=server.sessions.get(a),sb=server.sessions.get(b);sa.profile.shoppingMoney=10000;call(a,"checkout",o->{o.writeByte(0);o.writeShort(150);for(int k=1;k<7;k++)o.writeShort(0);},true);ok(sa.profile.shoppingMoney==9280&&(sa.profile.owned&150)==150,"Authoritative cart sells exactly the four added weapons");for(int id:new int[]{2,4,7,1}){call(a,"buy",o->o.writeByte(id),true);ok(sa.profile.equipped==id&&sa.profile.shoppingMoney==9280,"Owned new weapon "+id+" equips without another charge");}reject(null,"login",o->{o.writeUTF("new@717.test");o.writeUTF("test-password-123");},false,"Old client cannot load a new equipped weapon");ok(server.sessions.containsKey(a),"Rejected old login does not invalidate the current session");int ar=call(a,"create",o->{o.writeByte(1);o.writeByte(0);o.writeByte(-1);},true).readInt();int br=call(b,"create",o->{o.writeByte(1);o.writeByte(0);o.writeByte(-1);},false).readInt();ok(!server.matchmaker.compatible(server.rooms.get(ar),server.rooms.get(br)),"Matchmaker separates weapon-rule versions");reject(b,"join",o->{o.writeInt(ar);o.writeByte(1);},false,"Legacy client cannot join the eight-weapon room");DataInputStream rooms=call(b,"rooms",null,false);ok(rooms.readUnsignedShort()==1,"Legacy room list excludes new weapon rooms");ok(call(a,"rooms",null,true).readUnsignedShort()==1,"New room list excludes legacy rooms");reject(b,"checkout",o->{o.writeByte(0);o.writeShort(4);for(int k=1;k<7;k++)o.writeShort(0);},false,"Legacy session cannot forge a new weapon purchase");}
 System.out.println("All arsenal 7.1.7 server checks passed");}
}
